package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Json;
import io.tenvyr.platform.Db;
import java.net.URI;
import java.util.*;

public final class Executors {
    private Executors(){}
    public static ObjectNode parseSnapshot(JsonNode raw){ObjectNode n=RuntimeConnectionService.object(raw,"descriptor",Set.of("schemaVersion","executorId","agent","kind","configHash","capabilities","connection","requestedModelId","localProfile","httpProfile"));if(!Json.text(n,"schemaVersion").equals("1")||!Set.of("http","kafka").contains(Json.text(n,"kind"))||!Json.text(n,"configHash").matches("[0-9a-f]{64}"))throw new RuntimeFailure("EXECUTOR_DESCRIPTOR_INVALID","Invalid executor identity");RuntimeConnectionService.bounded(n.get("executorId"),"executorId",255);RuntimeConnectionService.bounded(n.get("agent"),"agent",255);ObjectNode capabilities=RuntimeConnectionService.object(n.get("capabilities"),"capabilities",Set.of("cancel"));if(!capabilities.path("cancel").isBoolean())throw new RuntimeFailure("EXECUTOR_DESCRIPTOR_INVALID","Invalid capability");if(n.has("connection"))RuntimeConnectionService.parseConnectionReference(n.get("connection"));if(n.has("requestedModelId"))Coordination.modelId(n.get("requestedModelId"));if(n.has("localProfile"))parseLocalProfile(n.get("localProfile"));if(Json.text(n,"kind").equals("http")){JsonNode http=RuntimeConnectionService.object(n.get("httpProfile"),"httpProfile",Set.of("submitUrl","requestTimeoutMs","maxResponseBytes"));URI url=URI.create(RuntimeConnectionService.bounded(http.get("submitUrl"),"submitUrl",2048));if(!Set.of("http","https").contains(url.getScheme())||url.getHost()==null||url.getRawUserInfo()!=null)throw new RuntimeFailure("EXECUTOR_DESCRIPTOR_INVALID","Invalid HTTP URL");RuntimeConnectionService.positive(http,"requestTimeoutMs",Integer.MAX_VALUE);RuntimeConnectionService.positive(http,"maxResponseBytes",Integer.MAX_VALUE);}else if(n.has("httpProfile"))throw new RuntimeFailure("EXECUTOR_DESCRIPTOR_INVALID","Kafka descriptor carries HTTP profile");return n;}
    public static ObjectNode parseLocalProfile(JsonNode raw){ObjectNode n=RuntimeConnectionService.object(raw,"localProfile",Set.of("command","args","cwd","envAllowlist","secrets"));RuntimeConnectionService.absolute(n.get("command"),"command");RuntimeConnectionService.args(n.get("args"));if(n.has("cwd"))RuntimeConnectionService.absolute(n.get("cwd"),"cwd");for(String key:List.of("envAllowlist","secrets"))if(n.has(key))RuntimeConnectionService.envRefs(n.get(key));return n;}
    public static ObjectNode resolve(Db db,RuntimeConnectionService connections,JsonNode step,ObjectNode descriptor){JsonNode meta=step.path("metadata");String id=Json.text(meta,"tenvyrConnectionId",null);if(id==null){if(meta.has("tenvyrModelId"))throw new RuntimeFailure("MODEL_NOT_ALLOWED","Model requires typed connection selection");return parseSnapshot(descriptor);}ObjectNode revision=connections.claimRevision(db,id),result=descriptor.deepCopy();JsonNode profile=revision.path("profile");result.put("executorId",Json.text(profile,"executorId"));result.set("connection",RuntimeConnectionService.buildConnectionReference(revision));if(meta.has("tenvyrModelId"))result.put("requestedModelId",Coordination.modelId(meta.get("tenvyrModelId")));if(profile.has("cli")){JsonNode cli=profile.get("cli");ObjectNode local=Json.object("command",cli.get("command"),"args",cli.get("args"));for(String key:List.of("cwd","envAllowlist","secrets"))if(cli.has(key))local.set(key,cli.get(key));result.set("localProfile",local);}return parseSnapshot(result);}
}
